pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor) public {
        // actor is only used to exercise an arbitrary entry point; owner() must
        // always report the deployer, never the zero address.
        vm.assume(actor != address(0));
        // exercise the public surface from a fuzzed caller (admissible: any caller)
        vm.prank(actor);
        uint256 bal = c.balanceOf(actor);
        // general rule: owner() is invariant across all inputs and callers
        assertTrue(c.owner() != address(0) && c.owner() == address(this), "owner must be deployer, not zero");
    }
}

