// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address newOwner, address caller) public {
        // Admissible domain: transfer target must be nonzero (Ownable requires it)
        vm.assume(newOwner != address(0));
        // caller may be any address, including the zero address

        // current owner (deployer == this test contract) transfers ownership
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            // transfer may have succeeded (reference) or not (mutant); ignore here
        } catch {
            // mutant reverts here because owner() returns address(0)
        }

        // Rule: an arbitrary caller can successfully invoke setCaller if and only if
        // it is exactly the address that owner() reports.
        vm.prank(caller);
        bool ok;
        try c.setCaller(caller) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(
            (caller == c.owner()) == ok,
            "setCaller must succeed exactly for the address owner() returns"
        );
    }
}

