pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address x) public {
        vm.assume(x != address(0));
        // The current owner (the setUp deployer) transfers ownership to x.
        vm.prank(address(this));
        c.transferOwnership(x);
        // The new owner renounces ownership.
        vm.prank(x);
        c.renounceOwnership();
        // After renouncing, the owner is the zero address.
        assertTrue(c.owner() == address(0));
    }
}

