import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address actor) public {
        // owner() must be caller-independent: reading it from any address yields
        // the same value as reading it from the deployer.
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        vm.prank(address(this));
        address ownerFromDeployer = c.owner();

        vm.prank(actor);
        address ownerFromActor = c.owner();

        assertTrue(ownerFromActor == ownerFromDeployer);
    }
}

