import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        // actor is not the contract's stored owner (owner is address(this))
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // General rule: a non-owner caller can never complete transferOwnership.
        assertTrue(!ok, "non-owner must not be able to transfer ownership");
    }
}

