contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor1, address actor2, address actor3) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor3 != address(0));
        vm.assume(actor1 != address(this) && actor2 != address(this) && actor3 != address(this));
        vm.assume(actor1 != actor2 && actor1 != actor3 && actor2 != actor3);
        // transfer ownership to actor2
        vm.prank(address(this));
        c.transferOwnership(actor2);
        // now actor1 tries to transfer ownership again; in P this must revert
        vm.prank(actor1);
        bool ok;
        try c.transferOwnership(actor3) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "non-owner must not be able to transfer ownership after it changed hands");
    }
}

